INSERT INTO `administradores` (`id`, `nombre`, `contrasena`, `correo`, `codigo_unico`) VALUES
(1, 'Edith Alvarado', 'Edith1234*', 'edialvarado@gmail.com', NULL),
(2, 'Amy Carvajal', 'Ptoelquelolea1!', 'valentinacarvajal1006@gmail.com', NULL);
INSERT INTO `banco_preguntas` (`id`, `nivel`, `sesion`, `materia`, `enunciado`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `imagen`, `creado_por`) VALUES
(1, 'B', 1, 'Matemáticas', 'En una papelería, un paquete de 500 hojas de papel cuesta $15.000. Si un estudiante necesita comprar solamente 100 hojas de papel para un trabajo escolar, ¿cuánto dinero debe pagar manteniendo la misma relación de precio?', '$5.000', '$3.000', '$1.500', '$4.000', 'B', NULL, NULL),
(2, 'B', 1, 'Matemáticas', 'El rector de un colegio revisa el número de estudiantes que ingresaron a la biblioteca durante una semana y encuentra los siguientes datos: Lunes (20), Martes (35), Miércoles (15), Jueves (40) y Viernes (30). ¿Cuál es el promedio (media) diario de estudiantes que visitaron la biblioteca esa semana?', '28 estudiantes', '35 estudiantes', '25 estudiantes', '30 estudiantes', 'A', NULL, NULL),
(3, 'B', 1, 'Lectura Crítica', '\"El agua es un recurso vital, pero el acceso a ella no es igual para todos. En algunas regiones del planeta, las personas deben caminar varias horas al día bajo el sol solo para conseguir un balde de agua limpia. Mientras tanto, en las grandes ciudades, es común ver cómo se desperdician litros de agua lavando aceras con mangueras o dejando grifos abiertos sin necesidad. La falta de conciencia y la distribución desigual son los verdaderos motores de la crisis hídrica global\". Según el texto, la crisis mundial del agua se debe principalmente a:', 'La falta de conciencia humana y la repartición inequitativa del recurso.', 'El clima extremadamente caluroso de las regiones que no tienen ríos.', 'Las largas horas de caminata que realizan las personas en el campo.', 'La construcción excesiva de aceras y carreteras en las grandes ciudades.', 'A', NULL, NULL),
(4, 'B', 1, 'Lectura Crítica', 'En la frase del texto: \"La falta de conciencia y la distribución desigual son los verdaderos motores de la crisis hídrica global\", la palabra motores se utiliza con el significado de:', 'Máquinas que transforman la energía en movimiento para los autos.', 'Las consecuencias o resultados finales de una situación problemática.', 'Las causas originarias o motivos que impulsan un fenómeno.', 'Herramientas tecnológicas usadas para extraer agua subterránea.', 'C', NULL, NULL),
(5, 'B', 1, 'C. Naturales', 'En un bosque, las abejas van de flor en flor recolectando néctar para alimentarse y producir miel. Al hacer esto, transportan de manera accidental el polen pegado a sus cuerpos, lo que permite que las plantas se reproduzcan y den frutos. Esta relación biológica, donde ambas especies se benefician mutuamente, es un ejemplo de:', 'Parasitismo', 'Mutualismo', 'Competencia', 'Depredación', 'B', NULL, NULL),
(6, 'B', 1, 'C. Naturales', 'Un estudiante tiene dos esferas del mismo tamaño: una está hecha de madera y la otra está hecha de hierro. Al colocarlas en una balanza, nota que la esfera de hierro es mucho más pesada que la de madera. A pesar de ocupar el mismo espacio (volumen), la diferencia de peso demuestra que la esfera de hierro posee una mayor:', 'Temperatura', 'Solubilidad', 'Densidad', 'Elasticidad', 'C', NULL, NULL),
(7, 'B', 1, 'C. Ciudadanas', 'En un colegio de Colombia, los estudiantes de noveno grado proponen cambiar el uniforme deportivo por uno más cómodo. Para que esta propuesta sea escuchada y evaluada formalmente por las directivas de la institución, el representante estudiantil debe llevar la iniciativa ante el organismo donde participan docentes, padres y directivos. Este organismo se conoce como:', 'Consejo Directivo', 'Comisión de Convivencia', 'Asociación de Exalumnos', 'Personería Estudiantil', 'A', NULL, NULL),
(8, 'B', 1, 'C. Ciudadanas', 'Un niño de 14 años es obligado por sus padres a dejar el colegio para trabajar jornadas de 10 horas diarias en un local comercial, argumentando que la familia necesita más ingresos económicos. En esta situación, se está vulnerando directamente la Constitución Política de Colombia porque:', 'Los menores de edad solo pueden trabajar un máximo de 5 horas al día.', 'El trabajo comercial paga menos dinero que el trabajo en el campo.', 'Los derechos de los niños prevalecen sobre los demás y el Estado garantiza su educación.', 'Los padres de familia no tienen autoridad legal para decidir sobre sus hijos.', 'C', NULL, NULL),
(9, 'S', 1, 'Matemáticas', 'Una empresa de mensajería determina que el costo diario de operación C (en miles de pesos) para transportar x cantidad de paquetes está modelado por la función cuadrática C(x) = x² - 40x + 500. ¿Qué cantidad de paquetes x debe transportar la empresa para alcanzar su costo mínimo diario de operación?', '40 paquetes', '20 paquetes', '500 paquetes', '10 paquetes', 'B', NULL, NULL),
(10, 'S', 1, 'Matemáticas', 'En un colegio, el 60% de los estudiantes practica fútbol, el 30% practica baloncesto y el 10% practica ambos deportes. Si se elige un estudiante al azar y se descubre que practica fútbol, ¿cuál es la probabilidad de que también practique baloncesto?', '1/10', '1/3', '1/6', '1/2', 'C', NULL, NULL),
(11, 'S', 1, 'Lectura Crítica', '\"Nadie es justo por voluntad sino por la fuerza de la ley. Imaginemos que un hombre justo y uno injusto recibieran un anillo que los volviera invisibles. El injusto, claramente, robaría, violaría y asesinaría sin temor al castigo. Pero el hombre justo, al verse libre de la mirada social y de las sanciones legales, terminaría haciendo exactamente lo mismo. Esto demuestra que la justicia no es una virtud intrínseca del alma humana, sino un pacto de conveniencia basado en el miedo mutuo al castigo\" (Adaptación de La República de Platón). De acuerdo con la estructura argumentativa del texto, el ejemplo del anillo de invisibilidad se utiliza principalmente para:', 'Demostrar que los seres humanos son inherentemente buenos pero la sociedad los corrompe.', 'Sustentar la tesis de que la justicia se practica únicamente por temor a las consecuencias sociales y legales.', 'Proponer una solución fantástica para eliminar los delitos y la impunidad en las grandes ciudades.', 'Criticar a los gobiernos que no implementan leyes lo suficientemente severas contra los criminales.', 'B', NULL, NULL),
(12, 'S', 1, 'Lectura Crítica', 'Del texto anterior se puede inferir una concepción de la naturaleza humana que coincide con cuál de las siguientes afirmaciones:', 'El ser humano es un ser racional capaz de actuar éticamente sin necesidad de supervisión externa.', 'Las leyes son un obstáculo artificial que impide el desarrollo de la verdadera bondad del individuo.', 'El comportamiento moral es una fachada impuesta; en libertad absoluta, el egoísmo prima sobre el bien común.', 'La justicia es un valor absoluto que se aprende a través de la educación formal y la filosofía.', 'C', NULL, NULL),
(13, 'S', 1, 'C. Naturales', 'Un bloque se desliza hacia abajo por una rampa inclinada. En un primer ensayo, la rampa está completamente libre de fricción y el bloque llega al suelo con una energía cinética final E1. En un segundo ensayo, utilizando el mismo bloque y la misma rampa, se añade una superficie rugosa que genera fricción, y el bloque llega al suelo con una energía cinética final E2. Al comparar los dos ensayos, se puede afirmar correctamente que:', 'E1 = E2, porque la energía total del universo siempre se conserva de manera exacta.', 'E1 < E2, porque la fuerza de fricción acelera el cuerpo en la última parte del trayecto.', 'E1 > E2, porque una parte de la energía mecánica inicial se disipó en forma de calor debido al roce.', 'E1 = 0 y E2 > 0, porque la fricción es la única variable que permite acumular energía en movimiento.', 'C', NULL, NULL),
(14, 'S', 1, 'C. Naturales', 'El uso excesivo de fertilizantes nitrogenados en la agricultura arrastra grandes cantidades de nitratos hacia los ríos y lagos cercanos mediante el agua de lluvia. Este fenómeno altera el equilibrio del ecosistema acuático al provocar un crecimiento descontrolado de algas en la superficie, las cuales bloquean la luz solar y consumen todo el oxígeno disuelto al morir y descomponerse. Este proceso de degradación ambiental se conoce como:', 'Fotosíntesis inversa', 'Eutrofización', 'Efecto invernadero local', 'Nitrificación atmosférica', 'B', NULL, NULL),
(15, 'S', 1, 'C. Ciudadanas', 'Un sector político propone reducir drásticamente los impuestos a las grandes empresas nacionales y extranjeras, argumentando que esto atraerá mayor inversión privada, generará nuevos puestos de trabajo y dinamizará la economía a largo plazo. Por el contrario, un sindicato de trabajadores se opone firmemente a la medida, señalando que la reducción de impuestos disminuirá los recursos del Estado para inversión social, ensanchando la brecha de desigualdad. En esta situación, el conflicto de intereses entre ambos sectores se origina principalmente en:', 'Una diferencia ideológica sobre el rol que debe tener el Estado en la recaudación y redistribución de la riqueza.', 'El desconocimiento total por parte del sindicato sobre el funcionamiento de las leyes comerciales del país.', 'La intención oculta de las grandes empresas de quebrar el aparato público para no pagar salarios mínimos.', 'Un desacuerdo técnico sobre los meses exactos en que se debe aplicar el cobro de aranceles de aduana.', 'A', NULL, NULL),
(16, 'S', 1, 'C. Ciudadanas', 'Un ciudadano colombiano nota que la alcaldía de su municipio planea talar un bosque nativo protegido para construir un centro comercial privado, afectando el derecho colectivo a un ambiente sano de toda la comunidad local. ¿Cuál es el mecanismo constitucional idóneo que debe interponer este ciudadano para proteger este derecho colectivo de inmediato?', 'Acción de Tutela', 'Derecho de Petición', 'Acción Popular', 'Habeas Corpus', 'C', NULL, NULL),
(17, 'A', 1, 'Matemáticas', 'Un servicio de taxi cobra una tarifa fija de $3.000 por abordar el vehículo y $1.200 por cada kilómetro recorrido. Si x representa los kilómetros recorridos, ¿cuál de las siguientes expresiones modela el costo total (C) del viaje?', 'C = 3.000x + 1.200', 'C = 1.200x + 3.000', 'C = 4.200x', 'C = 3.000x / 1.200', 'B', NULL, NULL),
(18, 'A', 1, 'Matemáticas', 'Una caja de zapatos tiene forma de prisma rectangular con las siguientes dimensiones: 30 cm de largo, 20 cm de ancho y 10 cm de alto. ¿Cuál es el volumen total de la caja?', '600 cm³', '60 cm³', '6.000 cm³', '120 cm³', 'C', NULL, NULL),
(19, 'A', 1, 'Lectura Crítica', 'Observa la tira cómica de Gaturro y responde la pregunta. En ella, el profesor pregunta a varios alumnos si ciertas palabras (\"examen\", \"escrúpulo\", \"alpiste\", \"calvicie\") se acentúan, y en la última viñeta Gaturro, sentado en su pupitre, piensa \"Con los años, sí...\", representado con una serie de círculos que suben desde su cabeza hasta un globo con el texto. ¿Qué función cumplen los círculos que aparecen sobre la cabeza de Gaturro en el último recuadro?', 'Representan globos inflables que flotan sobre el personaje.', 'Indican que el personaje responde con una broma, no literalmente.', 'Indican los pensamientos del personaje, no sus palabras en voz alta.', 'Representan un signo de admiración por la sorpresa del personaje al ser interrogado.', 'C', '/gaturro-acentuacion.jpg', NULL),
(20, 'A', 1, 'Lectura Crítica', 'Observa la tira cómica de Gaturro y responde la pregunta. En ella, el profesor pregunta a varios alumnos si ciertas palabras (\"examen\", \"escrúpulo\", \"alpiste\", \"calvicie\") se acentúan, y en la última viñeta Gaturro, sentado en su pupitre, piensa \"Con los años, sí...\", representado con una serie de círculos que suben desde su cabeza hasta un globo con el texto. ¿Qué función cumplen los círculos que aparecen sobre la cabeza de Gaturro en el último recuadro?', 'Representan globos inflables que flotan sobre el personaje.', 'Indican que el personaje responde con una broma, no literalmente.', 'Indican los pensamientos del personaje, no sus palabras en voz alta.', 'Representan un signo de admiración por la sorpresa del personaje al ser interrogado.', 'C', '/gaturro-acentuacion.jpg', NULL),
(21, 'A', 1, 'C. Naturales', 'Un automóvil viaja por una carretera recta a una velocidad constante de 20 metros por segundo (m/s) durante un tiempo de 30 segundos. ¿Qué distancia total recorrió el automóvil en ese intervalo de tiempo?', '50 metros', '10 metros', '600 metros', '1.500 metros', 'C', NULL, NULL),
(22, 'A', 1, 'C. Naturales', 'Durante una práctica de laboratorio, se hace reaccionar gas hidrógeno (H2) con gas oxígeno (O2) para producir agua líquida (H2O), liberando una gran cantidad de calor al entorno. De acuerdo con este comportamiento térmico, esta reacción se clasifica como:', 'Endotérmica', 'Exotérmica', 'De descomposición', 'Neutra', 'B', NULL, NULL),
(23, 'A', 1, 'C. Ciudadanas', 'Durante la primera mitad del siglo XX en Colombia, el proceso de industrialización y la búsqueda de mejores condiciones de vida provocaron un fenómeno social masivo conocido como el \"éxodo rural\". ¿Cuál fue la principal consecuencia demográfica de este fenómeno?', 'El abandono total de las principales actividades económicas en las costas del país.', 'Un crecimiento acelerado y desordenado de la población en las zonas urbanas.', 'La reducción drástica de la población que habitaba en las capitales de los departamentos.', 'El fin definitivo de la producción agrícola y cafetera en el territorio nacional.', 'B', NULL, NULL),
(24, 'A', 1, 'C. Ciudadanas', 'En Colombia, cuando el Congreso de la República debate, modifica y aprueba las leyes que rigen a toda la nación, está ejerciendo las funciones propias de cuál rama del poder público:', 'Rama Ejecutiva', 'Rama Judicial', 'Rama Legislativa', 'Órganos de Control', 'C', NULL, NULL),
(25, 'S', 2, 'Matemáticas', 'Un ingeniero necesita calcular la altura de una torre de telecomunicaciones. Para ello, se ubica a una distancia horizontal de 30 metros de la base de la torre y mide un ángulo de elevación de 45° hacia la parte más alta. ¿Cuál es la altura aproximada de la torre sin tener en cuenta la estatura del ingeniero?', '15 metros', '30 metros', '45 metros', '60 metros', 'B', NULL, NULL),
(26, 'S', 2, 'Matemáticas', 'En un estudio sobre el uso de transporte público, una alcaldía decide realizar una encuesta solo a las personas que salen de una estación de metro exclusiva de una zona residencial de altos ingresos entre las 7:00 a. m. y las 8:00 a. m. Con respecto a la validez de la muestra para inferir el comportamiento de toda la ciudad, se puede afirmar que:', 'Es completamente válida porque a esa hora toda la población se moviliza a sus trabajos.', 'Es inválida porque sesga los resultados al ignorar los hábitos de otros sectores socioeconómicos y horarios.', 'Es válida debido a que las estaciones de metro reciben un flujo constante y homogéneo de ciudadanos.', 'Es inválida únicamente porque el tamaño de la muestra debería incluir al 100% de los usuarios del sistema.', 'B', NULL, NULL),
(27, 'S', 2, 'C. Ciudadanas', 'Durante un debate sobre la implementación de programas de educación bilingüe (español y lenguas indígenas) en comunidades nativas, un funcionario afirma: \"La prioridad debe ser enseñar únicamente español, pues es el idioma que les permitirá integrarse plenamente a la economía de mercado y la modernidad del país\". Esta postura prioriza un enfoque de:', 'Asimilación cultural, subordinando la preservación de la identidad lingüística nativa al desarrollo económico individual.', 'Pluriculturalidad, buscando un equilibrio equitativo entre las tradiciones ancestrales y las demandas globales.', 'Autonomía territorial, permitiendo que las propias comunidades decidan sus métodos de aprendizaje formal.', 'Segregación social, aislando a las poblaciones vulnerables del resto del aparato productivo nacional.', 'A', NULL, NULL),
(28, 'S', 2, 'C. Ciudadanas', 'Ante el incremento de hurtos en un barrio, un grupo de vecinos decide organizarse en una \"brigada de seguridad armada\", deteniendo a sospechosos y aplicando castigos físicos públicos sin dar aviso a las autoridades. Esta acción comunitaria vulnera la Constitución Política de Colombia principalmente porque:', 'Los ciudadanos comunes no tienen permitido hablar en nombre de toda la junta de acción comunal.', 'El monopolio legítimo de la fuerza y la administración de justicia corresponden exclusivamente al Estado.', 'Los castigos físicos solo pueden aplicarse si se cuenta con la aprobación escrita del alcalde local.', 'La seguridad ciudadana es una responsabilidad exclusiva de las empresas privadas de vigilancia.', 'B', NULL, NULL),
(29, 'S', 2, 'C. Naturales', 'Un gas ideal se encuentra encerrado en un recipiente hermético de volumen constante. Si la temperatura absoluta del gas se duplica mediante la adición de calor externo, ¿qué ocurrirá con la presión ejercida por las partículas del gas contra las paredes del recipiente?', 'La presión se duplicará, de acuerdo con la ley de Gay-Lussac.', 'La presión disminuirá a la mitad, debido al aumento del espacio disponible.', 'La presión se mantendrá igual, ya que el volumen del recipiente no cambió.', 'La presión se cuadruplicará, porque las partículas pierden energía cinética.', 'A', NULL, NULL),
(30, 'S', 2, 'C. Naturales', 'En una especie de plantas, el alelo para las flores rojas (R) es completamente dominante sobre el alelo para las flores blancas (r). Si se cruzan dos plantas heterocigotas (Rr), ¿cuál es la probabilidad genotípica esperada para la descendencia en la primera generación filial (F1)?', '100% plantas heterocigotas (Rr).', '50% homocigotas dominantes (RR) y 50% homocigotas recesivas (rr).', '25% homocigotas dominantes (RR), 50% heterocigotas (Rr) y 25% homocigotas recesivas (rr).', '75% plantas con flores rojas y 25% plantas con flores blancas.', 'C', NULL, NULL),
(31, 'S', 2, 'Inglés', 'Read the text and choose the correct word for the blank space: \"Climate change is one of the most critical challenges of our century. Scientists argue that human activities ________ responsible for the rapid increase in global temperatures over the last few decades.\"', 'is', 'are', 'was', 'been', 'B', NULL, NULL),
(32, 'S', 2, 'Inglés', 'Choose the most appropriate response to complete the conversation: Speaker 1: \"I\'m really nervous about the final physics exam tomorrow. I don\'t feel prepared enough.\" Speaker 2: \"________________________\"', 'Don\'t worry, you have already studied a lot and you will do great.', 'Yes, physics is definitely my favorite subject at school.', 'I think the classroom is on the second floor next to the lab.', 'Yesterday I bought a new book about space exploration.', 'A', NULL, NULL),
(33, 'A', 2, 'Matemáticas', 'Un topógrafo quiere medir el ancho de un río. Se ubica en una orilla directamente frente a un árbol situado en la orilla opuesta. Luego, camina 10 metros en línea recta a lo largo de su orilla y mide un ángulo de 60° entre su posición actual y el árbol. Si la tangente de 60° es aproximadamente 1.73, ¿cuál es el ancho aproximado del río?', '5.7 metros', '10.0 metros', '17.3 metros', '20.0 metros', 'C', NULL, NULL),
(34, 'A', 2, 'Matemáticas', 'Para ingresar a un parque de diversiones, la entrada de 2 adultos y 3 niños cuesta $35.000 en total. Al día siguiente, bajo las mismas tarifas, la entrada de 3 adultos y 1 niño cuesta $31.000. ¿Cuál es el precio individual de la entrada de un adulto?', '$10.000', '$8.000', '$5.000', '$9.000', 'D', NULL, NULL),
(35, 'A', 2, 'C. Ciudadanas', 'El alcalde de un municipio propone construir una autopista que pasará por encima de una zona residencial de bajos recursos, argumentando que la obra reducirá los tiempos de viaje de miles de trabajadores de la ciudad. Los residentes de la zona se oponen porque la construcción implicará la demolición de sus viviendas y la pérdida de sus redes comunitarias. En esta situación, los intereses en conflicto son:', 'El desarrollo de la infraestructura urbana frente al derecho a la propiedad y la vivienda digna de una comunidad.', 'El enriquecimiento de las empresas privadas frente al presupuesto público asignado para las vías locales.', 'La recreación de los sectores de altos ingresos frente al cuidado ecológico de los bosques del municipio.', 'El libre comercio internacional frente a la protección de las fronteras terrestres del territorio nacional.', 'A', NULL, NULL),
(36, 'A', 2, 'C. Ciudadanas', 'Un grupo de ciudadanos colombianos considera que un artículo de la Constitución actual debe modificarse para endurecer las penas contra los delitos ambientales. Para lograr que la ciudadanía vote directamente en las urnas a favor o en contra de esta reforma constitucional específica, el mecanismo de participación idóneo que se debe convocar es:', 'Un plebiscito', 'Una consulta popular', 'Un referendo constitucional', 'Un cabildo abierto', 'C', NULL, NULL),
(37, 'A', 2, 'C. Naturales', 'Un ciclista que se desplaza por una pista recta con una velocidad inicial de 4 m/s decide acelerar uniformemente a razón de 2 m/s² durante un tiempo de 5 segundos. ¿Cuál es la velocidad final alcanzada por el ciclista al terminar ese intervalo de tiempo?', '10 m/s', '14 m/s', '20 m/s', '6 m/s', 'B', NULL, NULL),
(38, 'A', 2, 'C. Naturales', 'De acuerdo con la ley de conservación de la masa, una ecuación química debe estar correctamente balanceada para reflejar que el número de átomos de cada elemento es igual en los reactivos y en los productos. Al revisar la siguiente reacción de combustión incompleta del metano: CH4 + X O2 → CO2 + 2H2O. ¿Cuál debe ser el valor del coeficiente X para que la ecuación cumpla con dicha ley?', '1', '3', '4', '2', 'D', NULL, NULL),
(39, 'A', 2, 'Inglés', 'Read the text and choose the correct option for the blank space: \"Learning a second language is very beneficial for teenagers. Research shows that bilingual students ________ better cognitive flexibility and problem-solving skills compared to those who only speak one language.\"', 'develops', 'develop', 'developing', 'developed', 'B', NULL, NULL),
(40, 'A', 2, 'Inglés', 'Choose the most appropriate response to complete the short conversation: Speaker 1: \"Can you help me clean the laboratory before the chemistry teacher arrives?\" Speaker 2: \"________________________\"', 'Yes, I love reading history books on weekends.', 'Of course, let\'s start by organizing these test tubes.', 'No, the classroom is next to the principal\'s office.', 'I went to the cinema with my family last night.', 'B', NULL, NULL),
(41, 'B', 2, 'Matemáticas', 'En una granja hay gallinas y conejos. Si en total se cuentan 20 cabezas y 50 patas, ¿cuál de los siguientes sistemas de ecuaciones lineales permite hallar correctamente la cantidad de gallinas (x) y conejos (y) que hay en la granja?', 'x + y = 50; 2x + 4y = 20', 'x + y = 20; 4x + 2y = 50', 'x + y = 20; 2x + 4y = 50', 'x + y = 70; 2x + 2y = 50', 'C', NULL, NULL),
(42, 'B', 2, 'Matemáticas', 'Un estudiante quiere diseñar una cometa con forma de rombo. Sabe que la diagonal mayor mide 40 cm y la diagonal menor mide 20 cm. ¿Qué cantidad de papel en centímetros cuadrados necesita para cubrir la superficie de la cometa?', '800 cm²', '400 cm²', '200 cm²', '60 cm²', 'B', NULL, NULL),
(43, 'B', 2, 'C. Ciudadanas', 'Un grupo de ciudadanos pertenecientes a una comunidad afrodescendiente denuncia que una empresa minera comenzó a excavar cerca de sus tierras ancestrales sin haberles informado previamente ni consultado sobre el impacto ambiental. En Colombia, el mecanismo constitucional específico que protege a las minorías étnicas garantizando su participación antes de estos proyectos se denomina:', 'Consulta previa', 'Derecho de petición', 'Acción de tutela', 'Plebiscito popular', 'A', NULL, NULL),
(44, 'B', 2, 'C. Ciudadanas', 'En varias regiones andinas de Colombia, la tala indiscriminada de bosques nativos en las partes altas de las montañas para ampliar la frontera agrícola ha generado graves consecuencias río abajo. ¿Cuál es el principal impacto ambiental y de riesgo que sufre la comunidad de las zonas bajas debido a esta deforestación?', 'El aumento drástico de las nevadas durante el invierno.', 'La erosión del suelo y un mayor riesgo de deslizamientos e inundaciones en épocas de lluvia.', 'La desaparición inmediata de la producción industrial en las grandes ciudades de la costa.', 'El enfriamiento de la temperatura promedio del agua de los ríos locales.', 'B', NULL, NULL),
(45, 'B', 2, 'C. Naturales', 'Un libro se encuentra en reposo absoluto sobre una mesa horizontal. Al analizar las fuerzas que actúan sobre el libro, se puede afirmar correctamente que:', 'No actúa ninguna fuerza sobre él, por eso no se mueve.', 'La fuerza de gravedad lo atrae hacia abajo y la mesa ejerce una fuerza normal de igual magnitud hacia arriba.', 'La fuerza normal de la mesa es mucho mayor que el peso del libro, lo que evita que se caiga.', 'Solo actúa la fuerza de fricción que lo empuja hacia los lados manteniéndolo estático.', 'B', NULL, NULL),
(46, 'B', 2, 'C. Naturales', 'En una cadena alimenticia de un jardín, los caracoles se alimentan de las hojas de las plantas, y los pájaros se comen a los caracoles. En este ecosistema, ¿qué nivel trófico ocupan los caracoles?', 'Productores primarios', 'Consumidores primarios', 'Consumidores secundarios', 'Descomponedores', 'B', NULL, NULL),
(47, 'B', 2, 'Inglés', 'Read the sentence and choose the correct word to complete the blank space: \"My brother is very athletic. He usually ________ basketball with his classmates after school on Fridays.\"', 'play', 'plays', 'playing', 'played', 'B', NULL, NULL),
(48, 'B', 2, 'Inglés', 'Choose the most appropriate response to complete the short conversation: Speaker 1: \"Excuse me, do you know where the school library is?\" Speaker 2: \"________________________\"', 'Yes, I am preparing for my English test.', 'It\'s on the second floor, right next to the laboratory.', 'I bought a very interesting storybook yesterday.', 'No, thank you, I don\'t want any food.', 'B', NULL, NULL);
