INSERT INTO `respuestas_detalle` (`id`, `resultado_id`, `pregunta_id`, `materia`, `enunciado`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `opcion_elegida`, `respuesta_correcta`, `es_correcta`, `imagen`) VALUES
(193, 45, 41, 'Matemáticas', 'En una granja hay gallinas y conejos. Si en total se cuentan 20 cabezas y 50 patas, ¿cuál de los siguientes sistemas de ecuaciones lineales permite hallar correctamente la cantidad de gallinas (x) y conejos (y) que hay en la granja?', 'x + y = 50; 2x + 4y = 20', 'x + y = 20; 4x + 2y = 50', 'x + y = 20; 2x + 4y = 50', 'x + y = 70; 2x + 2y = 50', 'B', 'C', 0, NULL),
